use std::io::{self, Read};

trait Pricing {
    fn total(&self, qty: u64, unit: u64) -> u64;
}

struct Plain;
struct Bulk;
struct Member;

impl Pricing for Plain {
    fn total(&self, qty: u64, unit: u64) -> u64 {
        qty * unit
    }
}

impl Pricing for Bulk {
    fn total(&self, qty: u64, unit: u64) -> u64 {
        let t = qty * unit;
        if qty >= 10 {
            t - t * 10 / 100
        } else {
            t
        }
    }
}

impl Pricing for Member {
    fn total(&self, qty: u64, unit: u64) -> u64 {
        let t = qty * unit;
        let mut r = t - t * 5 / 100;
        if qty >= 3 {
            r = r.saturating_sub(100);
        }
        r
    }
}

fn fmt(c: u64) -> String {
    format!("${}.{:02}", c / 100, c % 100)
}

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut sum = 0u64;
    for line in s.lines() {
        let p: Vec<&str> = line.split_whitespace().collect();
        if p.is_empty() {
            continue;
        }
        if p.len() < 4 {
            println!("{} invalid kind", p[0]);
            continue;
        }
        let qty: u64 = p[1].parse().unwrap_or(0);
        let unit: u64 = p[2].parse().unwrap_or(0);
        let strat: Option<Box<dyn Pricing>> = match p[3] {
            "plain" => Some(Box::new(Plain)),
            "bulk" => Some(Box::new(Bulk)),
            "member" => Some(Box::new(Member)),
            _ => None,
        };
        match strat {
            Some(st) => {
                let t = st.total(qty, unit);
                sum += t;
                println!("{} {}", p[0], fmt(t));
            }
            None => println!("{} invalid kind", p[0]),
        }
    }
    println!("total {}", fmt(sum));
}

